BEGIN;
SET LOCAL ROLE revora_migrator;

-- A zero-character account must be canary-authorizable before genuine client
-- character creation. Runtime still revalidates that the authenticated
-- Character UID belongs to this immutable AccountId.
CREATE TABLE gameplay.account_feature_canaries (
    feature_key text NOT NULL REFERENCES gameplay.feature_rollouts(feature_key) ON DELETE CASCADE,
    account_id uuid NOT NULL REFERENCES identity.game_accounts(account_id) ON DELETE CASCADE,
    enabled_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    enabled_by text NOT NULL CHECK (length(enabled_by) BETWEEN 1 AND 100),
    PRIMARY KEY(feature_key,account_id)
);

CREATE TABLE game.ninja_canary_test_grants (
    character_id uuid PRIMARY KEY REFERENCES game.characters(character_id) ON DELETE RESTRICT,
    account_id uuid NOT NULL,
    legacy_character_uid integer NOT NULL CHECK (legacy_character_uid > 0),
    legacy_item_uids integer[] NOT NULL CHECK (cardinality(legacy_item_uids)=5),
    conquer_points_granted bigint NOT NULL CHECK (conquer_points_granted=1000000),
    granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    FOREIGN KEY(character_id,account_id) REFERENCES game.characters(character_id,account_id),
    FOREIGN KEY(character_id,legacy_character_uid) REFERENCES game.characters(character_id,legacy_uid)
);
CREATE TRIGGER ninja_canary_test_grants_append_only
BEFORE UPDATE OR DELETE ON game.ninja_canary_test_grants
FOR EACH ROW EXECUTE FUNCTION operations.reject_audit_mutation();

-- Rebirth is deliberately not part of ordinary native Ninja activation. It
-- remains separately gated until the generic lineage workflow is proven.
DELETE FROM gameplay.feature_gate_dependencies
WHERE feature_key='ninja.native' AND depends_on_feature_key='progression.rebirth';

