DO $validate_ninja_items$
BEGIN
    IF (SELECT count(*) FROM gameplay_reference.item_types
        WHERE source_id='51650035-0000-4e56-8000-000000000001') <> 548 THEN
        RAISE EXCEPTION 'Ninja item catalog count mismatch';
    END IF;
END
$validate_ninja_items$;

INSERT INTO gameplay_reference.item_type_release_entries(release_id,item_type,source_id)
SELECT r.release_id,i.item_type,i.source_id
FROM gameplay_reference.catalog_releases r
CROSS JOIN gameplay_reference.item_types i
WHERE r.release_state='active' AND i.source_id='51650035-0000-4e56-8000-000000000001'
ON CONFLICT DO NOTHING;

